// BUG-SEL5 · Deshacer (z) y rehacer (Z) restaura también las cajas de selección
//
// Al rotar o extruir en modo selección, la posición de los corchetes (mc.selCajas) cambia.
// Este parche intercepta mcPushHist, mcUndo y mcRedo para que las entradas de historial
// guarden el estado previo y posterior de mc.selCajas ({ selBefore, selAfter }), de forma
// que al pulsar 'z' o 'Z' los corchetes vuelvan a su posición exacta junto con los bloques.
//
// API:
//   game.selHistUndo.on()
//   game.selHistUndo.off()
//   game.selHistUndo.estado()

(() => {
'use strict';

let activo = false;
let origMcPushHist = null;
let origMcApplyHist = null;

function clonarCajas(cajas){
  if(!cajas || !cajas.length) return [];
  return cajas.map(c => ({
    a: [c.a[0], c.a[1], c.a[2]],
    b: [c.b[0], c.b[1], c.b[2]]
  }));
}

function patchedPushHist(en){
  if(mc.histLock) return;
  // Si la herramienta selección está activa y hay cajas, o la entrada trae selBefore/selAfter
  if(mc.tool === 'select' && mc.selCajas && mc.selCajas.length && !en.selBefore){
    // Si no trae selBefore explícito, capturamos el actual
    en.selAfter = clonarCajas(mc.selCajas);
    if(mc._selCajasBeforeEdit){
      en.selBefore = clonarCajas(mc._selCajasBeforeEdit);
      mc._selCajasBeforeEdit = null;
    } else {
      en.selBefore = clonarCajas(mc.selCajas);
    }
  }
  if(origMcPushHist) origMcPushHist(en);
}

// Interceptamos mcRotateSelBox y mcSelExtruir para capturar selBefore antes de mutar mc.selCajas
let origRotateSelBox = null;
let origSelExtruir = null;

function patchedRotateSelBox(eje){
  if(mc.selCajas && mc.selCajas.length){
    mc._selCajasBeforeEdit = clonarCajas(mc.selCajas);
  }
  return origRotateSelBox.apply(this, arguments);
}

function patchedSelExtruir(dir){
  if(mc.selCajas && mc.selCajas.length){
    mc._selCajasBeforeEdit = clonarCajas(mc.selCajas);
  }
  return origSelExtruir.apply(this, arguments);
}

async function patchedApplyHist(en, forward){
  if(origMcApplyHist) await origMcApplyHist(en, forward);

  // Restaurar cajas de selección si la entrada de historial las incluye
  if(en.selBefore && en.selAfter){
    const targetCajas = forward ? en.selAfter : en.selBefore;
    if(targetCajas && targetCajas.length){
      mc.selCajas = clonarCajas(targetCajas);
    }
  }
}

function instalar(){
  if(window.mcPushHist && !origMcPushHist){
    origMcPushHist = window.mcPushHist;
    window.mcPushHist = patchedPushHist;
  }
  if(window.mcApplyHist && !origMcApplyHist){
    origMcApplyHist = window.mcApplyHist;
    window.mcApplyHist = patchedApplyHist;
  }
  if(window.mcRotateSelBox && !origRotateSelBox){
    origRotateSelBox = window.mcRotateSelBox;
    window.mcRotateSelBox = patchedRotateSelBox;
  }
  if(window.mcSelExtruir && !origSelExtruir){
    origSelExtruir = window.mcSelExtruir;
    window.mcSelExtruir = patchedSelExtruir;
  }
  activo = true;
  console.log('✅ BUG-SEL5: historial de corchetes de selección instalado');
}

function desinstalar(){
  if(origMcPushHist){ window.mcPushHist = origMcPushHist; origMcPushHist = null; }
  if(origMcApplyHist){ window.mcApplyHist = origMcApplyHist; origMcApplyHist = null; }
  if(origRotateSelBox){ window.mcRotateSelBox = origRotateSelBox; origRotateSelBox = null; }
  if(origSelExtruir){ window.mcSelExtruir = origSelExtruir; origSelExtruir = null; }
  activo = false;
  console.log('❌ BUG-SEL5: historial de corchetes desinstalado');
}

const API = {
  on(){ if(!activo) instalar(); return 'BUG-SEL5 activado'; },
  off(){ if(activo) desinstalar(); return 'BUG-SEL5 desactivado'; },
  estado(){ return 'BUG-SEL5: ' + (activo ? 'ACTIVO' : 'inactivo'); }
};

game.selHistUndo = API;
API.on();
})();
